############################################# ### Generated from PreTeXt source ### ### https://pretextbook.org ### ############################################# ## DBsubject() ## DBchapter() ## DBsection() ## Level() ## KEYWORDS() ## TitleText1() ## EditionText1() ## AuthorText1() ## Section1(not reported) ## Problem1(3.7.4.12) ## Author() ## Institution() ## Language(en-US)
DOCUMENT();
############################################################ # Load Macros ############################################################ loadMacros( "PGstandard.pl", "PGML.pl", "AnswerFormatHelp.pl", "PCCmacros.pl", "parserRoot.pl", "contextForm.pl", "contextFraction.pl", "PGcourse.pl", ); COMMENT('Authored in PreTeXt');
############################################################ # Header ############################################################ TEXT(beginproblem());
############################################################ # PG Setup Code ############################################################ Context("Fraction"); $fname = list_random('f','g','h','j','k','p','m'); $x = list_random('q','r','t','x','y','z','w'); $n = random(3,9,1); $trig = list_random('sin','cos','tan','sec','cot','csc'); if($envir{problemSeed}==1){$fname='f';$x='t';$n=5;$trig='sec';}; Context()->variables->are($x=>'Real'); Context()->variables->set($x=>{limits=>[0,4]}); parser::Root->Enable; $f = Formula("root($n,$x)($trig($x)+e^$x)"); $fp = $f->D($x);
############################################################ # Body ############################################################
BEGIN_PGML Compute the derivative of the given function.
[`[$fname]([$x])=[$f]`]
[@KeyboardInstructions('To enter [`\sqrt{x}\text{,}`] type [|sqrt(x)|]*. To enter [`\sqrt[n]{x}\text{,}`] type [|root(n,x)|]*.')@]**
[_]{$fp}{80}
END_PGML
############################################################ # End Problem ############################################################
